select m.id,v.k,v.t,v.ft,v.r,v.s,v.o::jsonb from platform_modules m cross join (values
('notification-code','کد اعلان','text',true,10,'{}'),('notification-title','عنوان اعلان','text',true,20,'{}'),('notification-type','نوع اعلان','select',true,30,'{"options":["اطلاع‌رسانی","موفقیت","هشدار","خطا","اقدام","سیستمی"]}'),('channel','کانال نمایش','select',true,40,'{"options":["داخل سامانه","مرکز اعلان","پیامک","ایمیل","اعلان مرورگر","همه"]}'),('audience','مخاطب','select',true,50,'{"options":["عمومی","کاربران واردشده","نقش‌محور","سازمانی","کاربر مشخص"]}'),('trigger-event','رویداد محرک','text',false,60,'{}'),('target-route','مسیر مقصد','text',false,70,'{}'),('message-reference','مرجع پیام','text',false,80,'{}'),('priority','اولویت','number',true,90,'{}'),('delivery-mode','نحوه ارسال','select',true,100,'{"options":["فوری","صف ارسال","زمان‌بندی شده"]}'),('status','وضعیت','select',true,110,'{"options":["پیش‌نویس","فعال","غیرفعال","آرشیو شده"]}'),('scheduled-at','زمان‌بندی ارسال','text',false,120,'{}'),('expires-at','زمان انقضا','text',false,130,'{}'),('read-mode','وضعیت خواندن','select',true,140,'{"options":["قابل خواندن","نیازمند تأیید","خودکار"]}'),('notes','یادداشت','textarea',false,150,'{}')
) v(k,t,ft,r,s,o) where m.code='39-frontend-notifications' on conflict(module_id,field_key) do update set title=excluded.title,field_type=excluded.field_type,required=excluded.required,sort_order=excluded.sort_order,options=excluded.options;
