insert into platform_modules(code,title,is_active) values ('39-frontend-notifications','مدیریت اعلان‌های فرانت‌اند',true) on conflict(code) do update set title=excluded.title,is_active=true;
insert into module_field_definitions(module_id,field_key,title,field_type,required,sort_order,options)
insert into module_actions(module_id,action_code,title,permission) select m.id,v.a,v.t,v.p from platform_modules m cross join (values
('read','مشاهده اعلان‌ها','modules:39-frontend-notifications:read'),('write','ساخت و ویرایش اعلان','modules:39-frontend-notifications:write'),('delete','حذف اعلان','modules:39-frontend-notifications:delete'),('publish','فعال‌سازی اعلان','modules:39-frontend-notifications:publish'),('disable','غیرفعال‌سازی اعلان','modules:39-frontend-notifications:disable'),('duplicate','تکثیر اعلان','modules:39-frontend-notifications:duplicate'),('schedule','زمان‌بندی اعلان','modules:39-frontend-notifications:schedule')) v(a,t,p) where m.code='39-frontend-notifications' on conflict(module_id,action_code) do update set title=excluded.title,permission=excluded.permission;